'use client'

import React from 'react'
import WeatherCard from './WeatherCard'
import StockCard from './StockCard'

interface MessageProps {
  role: 'user' | 'assistant'
  content: string
  components?: Array<{
    type: string
    data: any
  }>
  isStreaming?: boolean
}

export default function Message({ role, content, components, isStreaming }: MessageProps) {
  const isUser = role === 'user'

  return (
    <div className={`flex ${isUser ? 'justify-end' : 'justify-start'} mb-4`}>
      <div className={`max-w-[80%] ${isUser ? 'order-2' : 'order-1'}`}>
        <div className={`flex items-start gap-3 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>
          <div className={`w-8 h-8 rounded-full flex items-center justify-center ${
            isUser ? 'bg-blue-500' : 'bg-gray-600'
          }`}>
            {isUser ? (
              <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
              </svg>
            ) : (
              <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.75 17L9 20l-1 1h8l-1-1-.75-3M3 13h18M5 17h14a2 2 0 002-2V5a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
              </svg>
            )}
          </div>
          
          <div className="flex-1">
            {content && (
              <div className={`rounded-lg px-4 py-2 ${
                isUser 
                  ? 'bg-blue-500 text-white' 
                  : 'bg-gray-100 dark:bg-gray-800 text-gray-900 dark:text-white'
              }`}>
                <p className="whitespace-pre-wrap">{content}</p>
                {isStreaming && (
                  <span className="inline-block w-2 h-4 bg-current animate-pulse ml-1" />
                )}
              </div>
            )}
            
            {components && components.length > 0 && (
              <div className="mt-3 space-y-3">
                {components.map((component, index) => {
                  if (component.type === 'weather' && component.data) {
                    return <WeatherCard key={index} data={component.data} />
                  } else if (component.type === 'stock' && component.data) {
                    return <StockCard key={index} data={component.data} />
                  } else if (component.type === 'text' && component.data?.content) {
                    return (
                      <div key={index} className="rounded-lg px-4 py-2 bg-gray-100 dark:bg-gray-800 text-gray-900 dark:text-white">
                        <p className="whitespace-pre-wrap">{component.data.content}</p>
                      </div>
                    )
                  }
                  return null
                })}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  )
} 